int climb(int n) {
    if (n <= 2) return n;
    int prev2 = 1, prev1 = 2;             // ways to reach steps 1 and 2
    for (int i = 3; i <= n; i++) {
        int cur = prev1 + prev2;
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;                         // O(1) space
}

